let carComparison=null;
function comparisonChoose(id){
 const cars=db.cars.slice().sort((a,b)=>a.name.localeCompare(b.name));if(cars.length<2){modal('Compare cars','<p>Add a second car to compare your collection.</p>',null);return;}
 const first=cars.some(c=>c.id===id)?id:(cars.some(c=>c.id===carComparison?.ids?.[0])?carComparison.ids[0]:cars[0].id),second=cars.some(c=>c.id===carComparison?.ids?.[1]&&c.id!==first)?carComparison.ids[1]:cars.find(c=>c.id!==first).id;
 carComparison={choices:cars,ids:[first,second],databaseId:db.id};showComparisonChooser();
}
function showComparisonChooser(){const s=carComparison;modal('Choose two cars',`<p>Compare their current specifications and optionally choose recorded runs to compare measured pace.</p><div class="form-grid">${['First car','Second car'].map((label,i)=>`<label class="field">${label}<select name="compare-${i}" required>${s.choices.map(c=>`<option value="${esc(c.id)}" ${s.ids[i]===c.id?'selected':''}>${esc(c.name)}${c.archived?' · Archived':''}</option>`).join('')}</select></label>`).join('')}</div>`,async values=>{const ids=[values['compare-0'],values['compare-1']];if(ids[0]===ids[1])throw Error('Choose two different cars.');const result=await api('plan','car.compare',{ids});if(result.databaseId!==s.databaseId||db.id!==s.databaseId)throw Error('The collection changed. Choose the cars again.');Object.assign(s,result,{ids,differences:false,runIds:ids.map(id=>result.runs.find(r=>r.carId===id)?.id||'')});setTimeout(showCarComparison,0);},'Compare');}
function comparisonRows(rows,differences){const visible=rows.filter(([,a,b])=>!differences||JSON.stringify(a??'')!==JSON.stringify(b??''));return visible.length?`<div class="table-wrap"><table class="car-comparison-table"><thead><tr><th>Detail</th>${carComparison.cars.map(c=>'<th>'+esc(c.name)+'</th>').join('')}</tr></thead><tbody>${visible.map(([label,a,b])=>`<tr class="${JSON.stringify(a??'')!==JSON.stringify(b??'')?'comparison-different':''}"><th scope="row">${esc(label)}</th><td>${esc(Array.isArray(a)?a.join(', '):a??'—')||'—'}</td><td>${esc(Array.isArray(b)?b.join(', '):b??'—')||'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No differences in this section.</p>';}
function showCarComparison(){
 const s=carComparison;if(!s?.cars)return;const [a,b]=s.cars,technical=[...new Set([...Object.keys(a.technical||{}),...Object.keys(b.technical||{})])];
 const identity=[['Manufacturer','maker'],['Brand / marque','marque'],['Model','model'],['Scale','scale'],['Reference','reference'],['Race class','raceClass'],['Usage','usage'],['Availability','availability']].map(([label,key])=>[label,a[key],b[key]]);
 const specs=technical.map(key=>[techLabels[key]||key,a.technical?.[key],b.technical?.[key]]);specs.unshift(['Gear ratio',slotforgeDomain.gearRatioText(a.technical?.pinion,a.technical?.gear),slotforgeDomain.gearRatioText(b.technical?.pinion,b.technical?.gear)]);
 modal('Car comparison',`<div class="comparison-covers">${s.cars.map(c=>`<article>${c.picture?`<img src="${esc(thumbnailSource(c.picture))}" alt="${esc(c.name)}">`:icon('car')}<h3>${esc(c.name)}</h3>${c.archived?badge('Archived'):''}</article>`).join('')}</div><div class="actions mt">${btn('Change cars','car-compare-edit')}${btn(s.differences?'Show all details':'Show differences only','car-compare-differences')}</div>${db.id!==s.databaseId||db.revision!==s.revision?'<p class="note">The collection changed. Choose the cars again to refresh this comparison.</p>':''}<h3 class="mt">Car details</h3>${comparisonRows(identity,s.differences)}<h3 class="mt">Current configuration</h3><p class="tiny muted">Current specifications; recorded runs below retain the configuration used at the time.</p>${comparisonRows(specs,s.differences)}${s.customFields.length?'<h3 class="mt">Custom fields</h3>'+comparisonRows(s.customFields.map(f=>[f.label,a.custom?.[f.id],b.custom?.[f.id]]),s.differences):''}<h3 class="mt">Recorded performance</h3><div class="form-grid">${s.ids.map((id,i)=>`<label class="field">${esc(s.cars[i].name)}<select data-comparison-run="${i}"><option value="">Choose a recorded run</option>${s.runs.filter(r=>r.carId===id).map(r=>`<option value="${esc(r.id)}" ${s.runIds[i]===r.id?'selected':''}>${esc(paceDescription(r))}</option>`).join('')}</select></label>`).join('')}</div><div id="car-comparison-pace"></div>`,null);paintCarComparisonPace();
}
function paintCarComparisonPace(){const s=carComparison,runs=s.runIds.map(id=>s.runs.find(r=>r.id===id)),[a,b]=runs;if(!a||!b){$('#car-comparison-pace').innerHTML='<p class="muted mt">Choose one recorded run for each car. Cars without recorded laps can still be compared by specification.</p>';return;}
 const conditions=['trackKey','lane','driver','direction','voltage','magnetStatus'],different=conditions.filter(k=>a[k]!==b[k]),unknown=conditions.filter(k=>a[k]==='Unknown'||b[k]==='Unknown');
 const metrics=paceMetrics.map(([key,label])=>[label,timingSeconds(a[key]),timingSeconds(b[key])]);
 $('#car-comparison-pace').innerHTML=`<p class="note ${different.length?'':'info'} mt">${different.length?'Conditions differ: '+different.map(k=>({trackKey:'track/source',magnetStatus:'magnets'}[k]||k)).join(', ')+'. These runs are not a controlled comparison.':'Recorded conditions match.'}${unknown.length?' Some conditions are unknown; equal labels do not prove equal conditions.':''}</p>${comparisonRows([['Source',a.kind==='manual'?'Reported manual test':'Measured Timing laps',b.kind==='manual'?'Reported manual test':'Measured Timing laps'],['Track',a.track,b.track],['Lane',a.lane,b.lane],['Driver',a.driver,b.driver],['Laps',a.totalLaps,b.totalLaps],...metrics],false)}<h4 class="mt">Configurations recorded with these runs</h4>${comparisonRows([...new Set([...Object.keys(a.technical||{}),...Object.keys(b.technical||{})])].map(k=>[techLabels[k]||k,a.technical?.[k],b.technical?.[k]]),s.differences)}<p class="tiny muted">No inferred lap times or automatic winner. Manual figures remain reported values; Timing metrics exclude invalid/pit laps and ineligible record laps as appropriate. Classification adjustments do not change measured pace.</p>`;
}
async function carComparisonAction(action,id){
 if(action==='car-compare'){comparisonChoose(id);return true;}
 if(action==='car-compare-edit'){const latest=await api('read',{queryView:{page:'Cars',editor:{action:'car-compare'}}});acceptSnapshot(latest.data);comparisonChoose(carComparison?.ids?.[0]);return true;}
 if(action==='car-compare-differences'){carComparison.differences=!carComparison.differences;showCarComparison();return true;}
 if(action==='car-delete'){
  const plan=await api('plan','car.delete',{id});modal('Permanently delete '+plan.name,`<p>This removes the car, its photos, ${plan.counts.documents} documents/guides, ${plan.counts.setups} setups, ${plan.counts.tests} manual tests, ${plan.counts.jobs} workshop jobs and its history.</p><p>${plan.loosePieces} fitted pieces return to Used spares; ${plan.assemblies} assemblies return intact to Used assemblies. Purchase history is retained without the deleted job link.</p><p class="note">Timing sessions and previously received packages remain historical records. Other cars’ results are unaffected. Later Timing results for this missing car will be rejected. Archive the car instead if you want to keep its full record.</p><p>Export a complete backup first if you may need to recover this car. Existing backups and previously shared copies are not erased.</p><label class="field">Type the exact car name<input name="confirmName" autocomplete="off" required></label><label class="check-row mt"><input name="confirmed" type="checkbox" required>I understand this permanently deletes the car record${db.club?' after Dealership review':''}.</label>`,async values=>{await change('car.delete',{id,revision:plan.revision,confirmName:values.confirmName,confirmed:!!values.confirmed});selected.delete(id);carId=null;page='Cars';},db.club?'Submit deletion for review':'Permanently delete');return true;
 }
 if(action==='database-reset'){
  if(clubState?.active||db.club?.replica){modal('Reset this collection','<p>A connected copy cannot reset the official collection. Use the authoritative dealership computer, or switch to your personal collection.</p>',null);return true;}
  const p=await api('plan','database.reset');modal('Reset '+p.name,`<p>Start a completely empty collection. This removes all cars, inventory, catalogues, assemblies, workshop records, guides, setups, manual tests, Timing sessions, reviews and collection settings.</p>${dl([...Object.entries(p.counts).map(([key,value])=>[({cars:'Cars',parts:'Part records',assemblies:'Assemblies',jobs:'Workshop jobs',documents:'Documents and guides',setups:'Setups',tests:'Manual tests',supplies:'Workshop supplies',submissions:'Incoming packages'})[key],String(value)]),['Timing sessions',String(p.sessions)]])}<p class="note">A complete recovery backup is saved beside the database before resetting. If that fails, nothing is reset. The new collection gets a new identity. Sharing stops; Timing, Telemetry and Dealership copies must reconnect. Old queued results target the old collection and are rejected.</p><p>This affects this collection only. External exports, other computers and recovery backups remain unchanged.</p><label class="field">Type RESET<input name="confirmation" required autocomplete="off"></label>`,async values=>{const r=await api('file','database.reset',{databaseId:p.databaseId,revision:p.revision,confirmation:values.confirmation});acceptSnapshot(r.data);selected.clear();carId=null;carComparison=null;page='Overview';source='local';remote=null;const latest=await api('read',{queryView:{page:'Overview'}});acceptSnapshot(latest.data);net=latest.network;clubState=latest.club;collectionMeta=latest.collection;tableColumns=[...db.settings.columns];toast('Fresh collection created. Recovery backup: '+r.recovery);},'Back up and reset');return true;
 }
 return false;
}
document.addEventListener('change',e=>{if(e.target.dataset.comparisonRun!==undefined&&carComparison){carComparison.runIds[Number(e.target.dataset.comparisonRun)]=e.target.value;paintCarComparisonPace();}});
